package org.codex.nfsugpreview;
import java.util.*;
/** Original visible windows, backdrop span alignment and final OBJ/BG/backdrop colour rules. */
final class NativeHudRules {
 static final class Windows {private final byte[] visible,backdrop;Windows(byte[] v,byte[] b){visible=v;backdrop=b;}byte[] visible(){return visible.clone();}byte[] backdrop(){return backdrop.clone();}}
 private static int[] bounds(int value,int limit){int start=value>>>8,end=value&255;if(start>limit&&start>end)start=0;if(end>limit){end=limit;if(start>limit)start=limit;}return new int[]{start,end};}
 private static boolean axis(int value,int pos,int limit){int[] b=bounds(value,limit);return b[0]<=b[1]?pos>=b[0]&&pos<b[1]:pos>=b[0]||pos<b[1];}
 private static final class Span {final int end,control;Span(int e,int c){end=e;control=c;}}
 private static List<Span> insert(List<Span> spans,int start,int end,int control){if(end==0)return spans;List<Span> result=new ArrayList<>();int left=0,i=0;for(;i<spans.size();i++){Span span=spans.get(i);int right=span.end;if(start<right){if(start>left)result.add(new Span(start,span.control));result.add(new Span(end,control));if(end<right){result.add(spans.get(i++));}else{i++;while(i<spans.size()&&end>=spans.get(i).end)i++;}break;}result.add(span);left=right;}for(;i<spans.size();i++)result.add(spans.get(i));return result;}
 static Windows windows(int display,int row,int[] regs){if(regs==null||regs.length!=6||(display&0x8000)!=0||(display&~65535)!=0||row<0||row>=160)throw new IllegalArgumentException("Unsupported HUD windows");for(int v:regs)if((v&~65535)!=0)throw new IllegalArgumentException("Window register");byte[] visible=new byte[240],backdrop=new byte[240];for(int x=0;x<240;x++){int control=63;if((display&0x6000)!=0){control=regs[5]&63;for(int w=1;w>=0;w--)if((display&(0x2000<<w))!=0&&axis(regs[w],x,240)&&axis(regs[w+2],row,160))control=(regs[4]>>>(w*8))&63;}visible[x]=(byte)control;}List<Span> spans=new ArrayList<>();spans.add(new Span(240,(display&0x6000)!=0?regs[5]&63:63));for(int w=1;w>=0;w--)if((display&(0x2000<<w))!=0&&axis(regs[w+2],row,160)){int[] b=bounds(regs[w],240);int c=(regs[4]>>>(w*8))&63;if(b[0]>b[1]){spans=insert(spans,0,b[1],c);spans=insert(spans,b[0],240,c);}else spans=insert(spans,b[0],b[1],c);}int x=0;for(Span span:spans){int stop=Math.min(240,Math.max(span.end,(x+3)&~3));for(;x<stop;x++)backdrop[x]=(byte)span.control;}return new Windows(visible,backdrop);}
 static int pixel(int obj,int tag,int bg,int priority,int backdrop,int blend,int alpha,int brightness){int[] colors=new int[3],bits=new int[3];int count=0,mode=(tag>>>2)&3,effect=(blend>>>6)&3,ey=Math.min(brightness&31,16);if(obj!=0&&(bg==0||(tag&3)<=priority)){colors[count]=obj;bits[count++]=4;}if(bg!=0){colors[count]=bg;bits[count++]=2;}if(obj!=0&&bg!=0&&(tag&3)>priority){colors[count]=obj;bits[count++]=4;}colors[count]=backdrop;bits[count++]=5;if(effect>=2)for(int i=0;i<count;i++)if((blend&(1<<bits[i]))!=0&&!(bits[i]==4&&(mode==1||(tag&0x30000)!=0)))colors[i]=NativeObjScanline.effect(colors[i],effect,ey);boolean semi=bits[0]==4&&mode==1,mix=count>1&&(blend&(1<<(bits[1]+8)))!=0&&(semi||(effect==1&&(blend&(1<<bits[0]))!=0));if(semi&&!mix&&effect>=2&&(blend&((tag&0x20000)!=0?0x2400:0x2410))!=0)colors[0]=NativeObjScanline.effect(colors[0],effect,ey);int ea=Math.min(alpha&31,16),eb=Math.min((alpha>>>8)&31,16),result=0xff000000;for(int k=0;k<3;k++){int mask=255<<(k*8),c=colors[0]&mask;if(mix){c=(c*ea+(colors[1]&mask)*eb)/16;if((c>>>(k*8))>255)c=mask;}result|=c&mask;}return result;}
}
